/* Generated by Universal Website Clone Bot - progressive enhancement for reconstructed forms.
 * Submits form data as JSON to the reconstructed backend. Nothing is sent anywhere else. */
(function () {
  "use strict";
  var base = String(window.CLONE_API_BASE || "").replace(/\/$/, "");

  function message(form) {
    var el = form.querySelector(".clone-form-message");
    if (!el) {
      el = document.createElement("div");
      el.className = "clone-form-message";
      el.setAttribute("role", "status");
      form.appendChild(el);
    }
    return el;
  }

  function show(form, ok, text) {
    var el = message(form);
    el.textContent = text;
    el.className = "clone-form-message " + (ok ? "clone-ok" : "clone-error");
  }

  document.querySelectorAll("form[data-clone-form]").forEach(function (form) {
    form.addEventListener("submit", function (ev) {
      ev.preventDefault();
      var endpoint = form.getAttribute("data-clone-endpoint");
      var payload = {};
      new FormData(form).forEach(function (value, key) {
        if (typeof value !== "string") return;
        payload[key] = key in payload ? [].concat(payload[key], value) : value;
      });
      var button = form.querySelector("[type=submit]");
      if (button) button.disabled = true;
      fetch(base + endpoint, {
        method: "POST",
        headers: { "Content-Type": "application/json", "Accept": "application/json" },
        body: JSON.stringify(payload)
      }).then(function (res) {
        return res.json().catch(function () { return {}; }).then(function (data) {
          if (res.ok) {
            show(form, true, data.message || "Submitted successfully.");
            if (form.getAttribute("data-clone-kind") === "contact") form.reset();
          } else {
            var detail = data.detail;
            show(form, false, typeof detail === "string" ? detail : (detail && detail.errors ? detail.errors.join(" ") : "Submission failed."));
          }
        });
      }).catch(function () {
        show(form, false, "Could not reach the server.");
      }).then(function () {
        if (button) button.disabled = false;
      });
    });
  });
})();
